#   int 가 아니라 Quantity 를 받는 설계가 나온다
#   Quantity 안에서 0과 음수를 막을 수 있다

#   구현부터 하면 int 로 시작해서 int 로 끝난다

# --- 관심사가 하나씩 오는 것 ---

#   3.2절 사이클 1

public static int calculate(int price, int level) {
    return 9500;
}

#   소수점? 생각 안 했다
#   등급 표현? 생각 안 했다
#   예외? 생각 안 했다

#   사이클 3 에서 처음

public static int calculate(int price, int level) {
    if (level == 1) return (int) (price * 0.95);
    return (int) (price * 0.90);
}

#   (int) 캐스팅이 여기서 처음 나왔다

#   그리고 이 캐스팅이 맞는지 테스트가 묻는다

@DisplayName("할인 금액에 소수점이 생기면 버린다")
@Test
void discountWithFraction() {
    int result = DiscountCalculator.calculate(9999, 1);

    assertThat(result).isEqualTo(9499);   // 9499.05 -> 9499
}

$ ./gradlew test --tests DiscountCalculatorTest

DiscountCalculatorTest > 할인 금액에 소수점이 생기면 버린다 PASSED

#   버림이 맞나? 반올림이 맞나?

#   요구사항에 없다

#   테스트를 짜는 순간 물어야 하는 질문이 또 하나 나왔다

# --- 멈추는 지점 ---

$ ./gradlew test --tests DiscountCalculatorTest

